ACE_PID,ACE_START=2150612,"474251167"
def live(pid,tick):
    try:return Path(f"/proc/{pid}/stat").read_text().rsplit(")",1)[1].split()[19]==tick
    except (FileNotFoundError,ProcessLookupError):return False
def wait_for(paths,phase):
    while not all(p.is_file() for p in paths):
        if (RUN/"failure.json").exists():
            raise RuntimeError("Actual ACE failed before target "+phase)
        if not live(ACE_PID,ACE_START):
            raise RuntimeError("Original ACE handle missing before complete target "+phase)
        time.sleep(30)
def raws(out):
    found={}
    for p in (out/"native").rglob("*.json"):
        if p.name.endswith((".input.json",".answer.json")):continue
        value=read(p)
        if "calls" in value:found[str(p.relative_to(ROOT))]=value
    return found
def teachers(out):
    return {str(p.relative_to(ROOT)):read(p) for p in (out/"teacher").glob("*/response.json")}
def native_cost(values):
    assert all(len(v["calls"])==1 and v.get("response") is not None for v in values.values())
    return {"origins":len(values),"HTTP":sum(len(v["calls"]) for v in values.values()),
        "input_tokens":sum(v["response"]["prompt_tokens"] for v in values.values()),
        "output_tokens":sum(v["response"]["completion_tokens"] for v in values.values()),
        "finish_reasons":dict(collections.Counter(v["response"]["finish_reason"] for v in values.values()))}
def teacher_cost(values):
    usages=[v["invocation"]["usage"] for v in values.values()]
    return {"successful_responses":len(values),
        "attempts_accounted_by_success_metadata":sum(v.get("capacity_transport_attempt_index",0)+1 for v in values.values()),
        "known_input_tokens":sum(v["input_tokens"] for v in usages),
        "known_output_tokens":sum(v["output_tokens"] for v in usages),
        "reasoning_already_subset_of_output":sum(v.get("reasoning_output_tokens",0) for v in usages)}
def main():
    OUT.mkdir(exist_ok=False)
    if not live(ACE_PID,ACE_START):raise RuntimeError("Queue only against the actual live ACE04")
    RunStore.immutable_json(OUT/"queued.json",{"at":now(),"PID_start":[ACE_PID,ACE_START],
        "script_sha256":sha(Path(__file__)),"no_actor_teacher_TEST_or_restart":True,
        "one_readonly_tokenizer_metadata_query_only_after_publication":True})
    wait_for([RUN/"publications/b8.json"],"unique B8 publication")
    exec(PROGRAM,{"__name__":"__actual_B8_readonly__","PROGRAM":PROGRAM})
    audit=BASE/"ACEv4_Run04_B8_unique_actual_publication_all32_TRAIN_failed_public_text_exact_reflections_counters_ADD_and_true_union_cost_audit_20261023.json"
    checked=read(audit);names=set(checked["evidence_sha256"])
    names.update([str(audit.relative_to(ROOT)),str(Path(__file__).relative_to(ROOT)),
        str((OUT/"queued.json").relative_to(ROOT)),
        "configs/openexempt_ace_public_assets128_20261023_run04.json",
        "configs/openexempt_ace_public_assets128_20261023_run04.frozen.json"])
    receipt=preserve("legal_openexempt_Run04_actual_B8_publication_20261023","auto",names)
    RunStore.immutable_json(BASE/"ACEv4_Run04_actual_B8_publication_automatic_dual_preservation_20261023.json",{
        "at":now(),"members":len(names),"receipt":receipt,"both_disks_all_members_verified":True,
        "not_TEST_or_new_case_gain":True})
    wait_for([RUN/"completion.json",RUN/"terminal_preservation.json"],"complete terminal and preservation")
    complete=read(RUN/"completion.json")
    assert complete["status"]=="completed_declared_ACE_adaptation_stream" and len(complete["batch_summary"])==8
    cfg=read(ROOT/"configs/openexempt_ace_public_assets128_20261023_run04.json")
    current=read(ROOT/cfg["continuation_receipt"])
    previous_cfg=read(ROOT/current["source_config"])
    legacy=read(ROOT/previous_cfg["continuation_receipt"])
    previous_out=ROOT/"runs"/previous_cfg["run_id"]
    oldest_out=ROOT/"runs"/legacy["source_run_id"]
    retained_native={n:read(ROOT/n) for n in current["native_origins"]};retained_native.update(raws(RUN))
    retained_teachers={n:read(ROOT/n) for n in current["teacher_responses"]};retained_teachers.update(teachers(RUN))
    retired_B8_native={n:v for n,v in raws(previous_out).items() if n not in current["native_origins"]}
    retired_B8_teachers={n:v for n,v in teachers(previous_out).items() if n not in current["teacher_responses"]}
    retired_B3_native={n:v for n,v in raws(oldest_out).items() if n not in legacy["native_origins"]}
    retired_B3_teachers={n:v for n,v in teachers(oldest_out).items() if n not in legacy["teacher_responses"]}
    assert (len(retired_B3_native),len(retired_B3_teachers),len(retired_B8_native),len(retired_B8_teachers))==(10,12,5,7)
    pools=[retained_native,retired_B3_native,retired_B8_native]
    tpools=[retained_teachers,retired_B3_teachers,retired_B8_teachers]
    assert len(set().union(*pools))==sum(map(len,pools)) and len(set().union(*tpools))==sum(map(len,tpools))
    cost=native_cost(retained_native);tcost=teacher_cost(retained_teachers)
    assert cost["origins"]==complete["actual_native_calls"] and tcost["successful_responses"]==complete["actual_teacher_responses"]
    assert cost["input_tokens"]==complete["native_prompt_tokens"] and cost["output_tokens"]==complete["native_completion_tokens"]
    assert tcost["attempts_accounted_by_success_metadata"]==complete["actual_teacher_attempts"]
    legacy_attempts=sum(read(ROOT/n).get("capacity_transport_attempt_index",0)+1 for n in legacy["teacher_responses"])
    b3_attempts=read(oldest_out/"failure.json")["actual_teacher_attempts"]-legacy_attempts
    actual_attempts=complete["actual_teacher_attempts"]+b3_attempts+current["retired_uncommitted_teacher_attempts"]
    all_native={k:v for d in pools for k,v in d.items()};all_teachers={k:v for d in tpools for k,v in d.items()}
    ncost=native_cost(all_native);tall=teacher_cost(all_teachers)
    report={"at":now(),"classification":"Complete single seed45 ACE lineage including retired work; complete firsts are TRAIN not frozen-bank TEST",
        "run_id":cfg["run_id"],"complete_first_forecasts":complete["prequential"],
        "final_playbook_sha256":complete["final_playbook_sha256"],"published_bullets":checked["published_bullets"],
        "published_tokens":checked["actual_Qwen_tokens_independently_retokenized"],
        "retained": {"native":cost,"teachers":tcost},
        "retired_B3":{"native":native_cost(retired_B3_native),"teachers":teacher_cost(retired_B3_teachers),"attempts":b3_attempts},
        "retired_B8":{"native":native_cost(retired_B8_native),"teachers":teacher_cost(retired_B8_teachers),
            "attempts":current["retired_uncommitted_teacher_attempts"],"failed_timeout_usage_unknown_not_zero":True},
        "complete_actual_native_cost":ncost,"successful_teacher_known_usage_lower_bound":tall,
        "all_actual_teacher_attempts":actual_attempts,
        "attempts_without_known_success_usage":actual_attempts-len(all_teachers),
        "failed_usage_not_assigned_zero_or_folded_into_known_tokens":True,
        "native_origins":sorted(all_native),"teacher_response_paths":sorted(all_teachers),
        "single_learning_lineage_not_three_repeats":True,"no_sealed_TEST_access_or_method_change":True}
    dest=BASE/"ACEv4_Run04_complete128_terminal_actual_retained_and_retired_B3_B8_cost_NOT_TEST_20261023.json"
    RunStore.immutable_json(dest,report)
    names=[str(p.relative_to(ROOT)) for p in [dest,audit,RUN/"completion.json",RUN/"terminal_preservation.json",Path(__file__),OUT/"queued.json"]]
    saved=preserve("legal_openexempt_Run04_complete_terminal_cost_20261023","auto",names)
    RunStore.immutable_json(OUT/"complete.json",{"at":now(),"report":str(dest.relative_to(ROOT)),"preservation":saved})
    print(json.dumps({"at":now(),"actual_complete":True,"native_total_including_retired":ncost["origins"],
        "successful_teachers_including_retired":len(all_teachers),"attempts":actual_attempts,
        "not_final_TEST":True}),flush=True)
if __name__=="__main__":
    try:main()
    except Exception as error:
        if OUT.exists() and not (OUT/"analysis_failed.json").exists():
            RunStore.immutable_json(OUT/"analysis_failed.json",{"at":now(),"error":repr(error),
                "traceback":traceback.format_exc(),"analysis_error_not_asserted_model_or_learning_failure":True,
                "no_stop_restart_or_training_mutation":True})
        raise
